#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; ROOT="${ANVIL_DEPLOY_ROOT:-$(cd "$SCRIPT_DIR/../../.." && pwd)}"; REPO="$ROOT/repo"; PREVIOUS="$ROOT/runtime/previous.sha"; [[ -s "$PREVIOUS" ]] || exit 2
RUNTIME_ENV="$ROOT/runtime/anvil.env"; [[ -f "$RUNTIME_ENV" ]] || { echo 'runtime secret file is missing; rollback will not recreate it' >&2; exit 4; }; [[ "$(stat -c '%a' "$RUNTIME_ENV")" == "600" || "$(stat -c '%a' "$RUNTIME_ENV")" == "400" ]] || { echo 'runtime secret file must be mode 0600 (or stricter)' >&2; exit 4; }
SHA="$(tr -d '\r\n' < "$PREVIOUS")"; [[ "$SHA" =~ ^[0-9a-f]{40}$ ]] || exit 2; git -C "$REPO" cat-file -e "$SHA^{commit}"; [[ -z "$(git -C "$REPO" status --porcelain)" ]] || { echo 'checkout is dirty' >&2; exit 3; };
source "$REPO/deploy/ysna/manifest-guard.sh"; ANVIL_RELEASE_MANIFEST_REF="${ANVIL_RELEASE_MANIFEST_REF:-origin/main}"; validate_release_manifest "$REPO" "$ANVIL_RELEASE_MANIFEST_REF" "$SHA" rollback
ASSET_DIR="$(tr -d '\r\n' < "$ROOT/runtime/rollback-assets.current")"; ROLLBACK_COMPOSE="$ASSET_DIR/compose.production.yml"; ROLLBACK_VERIFY="$ASSET_DIR/verify.sh"; [[ -f "$ROLLBACK_COMPOSE" && -f "$ROLLBACK_VERIFY" ]] || { echo 'versioned rollback assets are missing' >&2; exit 5; }
ANVIL_RUNTIME_ENV_FILE="$RUNTIME_ENV" ANVIL_RELEASE_COMMIT="$SHA" docker compose -f "$ROLLBACK_COMPOSE" stop anvil-web; git -C "$REPO" checkout --detach "$SHA"; ANVIL_RUNTIME_ENV_FILE="$RUNTIME_ENV" ANVIL_RELEASE_COMMIT="$SHA" docker compose -f "$ROLLBACK_COMPOSE" up -d --no-build anvil-web; ANVIL_DEPLOY_ROOT="$ROOT" ANVIL_RUNTIME_ENV_FILE="$RUNTIME_ENV" "$ROLLBACK_VERIFY" "$SHA"; echo "application rollback complete; migration remains 0013_task_bootstrap_authority; runtime secret retained"
